if object_id('cdc_change_log') is not null drop table cdc_change_log
go
if object_id('cdc_offset') is not null drop table cdc_offset
go

-- One row per changed key per statement. change_id is the replication order.
create table cdc_change_log (
    change_id   numeric(18,0) identity,
    table_name  varchar(30)   not null,
    op          char(1)       not null,      -- I / U / D
    pk_value    varchar(30)   not null,
    change_ts   datetime      default getdate() not null,
    constraint pk_cdc_change_log primary key (change_id)
)
go

-- Consumer checkpoint: last change_id fully applied to the target.
create table cdc_offset (
    consumer        varchar(30)   not null,
    last_change_id  numeric(18,0) not null,
    updated_at      datetime      not null,
    constraint pk_cdc_offset primary key (consumer)
)
go

if object_id('trg_cdc_customer') is not null drop trigger trg_cdc_customer
go
create trigger trg_cdc_customer on customer for insert, update, delete as
begin
    insert cdc_change_log (table_name, op, pk_value)
    select 'customer', 'I', convert(varchar(30), i.customer_id) from inserted i
     where not exists (select 1 from deleted d where d.customer_id = i.customer_id)
    insert cdc_change_log (table_name, op, pk_value)
    select 'customer', 'U', convert(varchar(30), i.customer_id) from inserted i
     where exists (select 1 from deleted d where d.customer_id = i.customer_id)
    insert cdc_change_log (table_name, op, pk_value)
    select 'customer', 'D', convert(varchar(30), d.customer_id) from deleted d
     where not exists (select 1 from inserted i where i.customer_id = d.customer_id)
end
go

